const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && git status --short && rg -n \"Block props migrated|block props|migration|sidebar\" /home/sid/.codex/memories/MEMORY.md","max_output_tokens":5500}),
  tools.exec_command({cmd:"rg --files -g AGENTS.md -g CLAUDE.md -g '*migration*' -g '*migrate*' -g '*Sidebar*' -g '*sidebar*' -g package.json -g '*lock*' .github apps/roam .agents .claude 2>/dev/null","max_output_tokens":5000})
]); for (let i=0;i<results.length;i++) text({i,...results[i]});
text(ALL_TOOLS.filter(x=> /search/i.test(x.name+" "+x.description) && /github|tool/i.test(x.name+" "+x.description)).map(x=>({name:x.name,description:x.description.slice(0,250)})).slice(0,35));

const results = await Promise.allSettled([
tools.exec_command({cmd:"cat AGENTS.md apps/roam/AGENTS.md apps/roam/CLAUDE.md","max_output_tokens":6500}),
tools.exec_command({cmd:"git remote -v && git log -1 --format='%H %ci %s' && rg -n 'Block props migrated|migrateLegacyToBlockProps|migrateLeftSidebarSettings|LeftSidebarPersonalSettings|getLeftSidebarSettings|left-sidebar|leftSidebar' apps/roam/src .github","max_output_tokens":10000}),
tools.exec_command({cmd:"git log --all --since=2026-08-15 --format='%h %cs %s' -- apps/roam/src/components/settings/utils/migrateLegacyToBlockProps.ts apps/roam/src/utils/migrateLeftSidebarSettings.ts apps/roam/src/components/LeftSidebarView.tsx apps/roam/src/utils/getLeftSidebarSettings.ts && git rev-parse --verify 078990e8 && gh --version","max_output_tokens":4000})
]);for(let i=0;i<results.length;i++) text({i,...results[i]});
for(const name of ["mcp__codex_apps__github_search_prs","mcp__codex_apps__github_fetch"]) text(ALL_TOOLS.find(x=>x.name===name));

