208	const reconcileRelationKeys = (
209	  pageUid: string,
210	  globalBlockUid: string,
211	  relations: Record<string, json>,
212	): void => {
213	  const placeholderKeys = Object.keys(DEFAULT_RELATIONS_BLOCK_PROPS);
214	  const hasPlaceholders = placeholderKeys.some((k) => k in relations);
215	  if (!hasPlaceholders) {
216	    return;
217	  }
218	
219	  const pageChildren = getShallowTreeByParentUid(pageUid);
220	  const grammarBlock = pageChildren.find((c) =>
221	    toFlexRegex("grammar").test(c.text),
222	  );
223	  if (!grammarBlock) {
224	    return;
225	  }
226	
227	  const grammarChildren = getShallowTreeByParentUid(grammarBlock.uid);
228	  const relationsBlock = grammarChildren.find((c) =>
229	    toFlexRegex("relations").test(c.text),
230	  );
231	  if (!relationsBlock) {
232	    return;
233	  }
234	
235	  const relationBlocks = getShallowTreeByParentUid(relationsBlock.uid);
236	
237	  const labelToUid: Record<string, string> = {};
238	  for (const block of relationBlocks) {
239	    labelToUid[block.text] = block.uid;
240	  }
241	
242	  const placeholderToLabel: Record<string, string> = {};
243	  for (const [key, value] of Object.entries(DEFAULT_RELATIONS_BLOCK_PROPS)) {
244	    placeholderToLabel[key] = value.label;
245	  }
246	
247	  const reconciledRelations: Record<string, json> = {};
248	  let changed = false;
249	
250	  for (const [key, value] of Object.entries(relations)) {
251	    if (placeholderKeys.includes(key)) {
252	      const label = placeholderToLabel[key];
253	      const realUid = label ? labelToUid[label] : undefined;
254	      if (realUid) {
255	        reconciledRelations[realUid] = value;
256	        changed = true;
257	        continue;
258	      }
259	    }
260	    reconciledRelations[key] = value;
261	  }
262	
263	  if (changed) {
264	    setBlockProps(globalBlockUid, { Relations: reconciledRelations }, false);
265	  }
266	};
