 89	      const defaultSchema = current as z.ZodDefault<z.ZodTypeAny>;
 90	      current = defaultSchema._def.innerType;
 91	      didUnwrap = true;
 92	      continue;
 93	    }
 94	
 95	    if (current instanceof z.ZodOptional || current instanceof z.ZodNullable) {
 96	      current = current.unwrap() as z.ZodTypeAny;
 97	      didUnwrap = true;
 98	      continue;
 99	    }
100	
101	    if (current instanceof z.ZodEffects) {
