103	      current = effectsSchema._def.schema;
104	      didUnwrap = true;
105	      continue;
106	    }
107	
108	    if (current instanceof z.ZodCatch) {
109	      const catchSchema = current as z.ZodCatch<z.ZodTypeAny>;
110	      current = catchSchema._def.innerType;
111	      didUnwrap = true;
112	      continue;
113	    }
114	
115	    if (current instanceof z.ZodLazy) {
116	      const lazySchema = current as z.ZodLazy<z.ZodTypeAny>;
117	      current = lazySchema._def.getter();
118	      didUnwrap = true;
119	    }
120	  }
121	
