 62	export const deepEqual = (a: unknown, b: unknown): boolean => {
 63	  if (a === b) return true;
 64	  const isEmpty = (v: unknown) =>
 65	    v === undefined || v === null || v === "" || v === false;
 66	  if (isEmpty(a) && isEmpty(b)) return true;
 67	  if (a == null || b == null) return a === b;
 68	  if (Array.isArray(a) && Array.isArray(b)) {
 69	    if (a.length !== b.length) return false;
 70	    return a.every((v, i) => deepEqual(v, b[i]));
 71	  }
 72	  if (isRecord(a) && isRecord(b)) {
 73	    const keysA = Object.keys(a);
 74	    const keysB = Object.keys(b);
 75	    if (keysA.length !== keysB.length) return false;
 76	    return keysA.every((k) => k in b && deepEqual(a[k], b[k]));
 77	  }
 78	  return false;
 79	};
