  50	const createSettingsWatchCallback = <T>(
  51	  schema: { safeParse: (data: unknown) => { success: boolean; data?: T } },
  52	  onSettingsChange: (context: {
  53	    newSettings: T;
  54	    oldSettings: T | null;
  55	    before: PullBlock | null;
  56	    after: PullBlock | null;
  57	  }) => void,
  58	): PullWatchCallback => {
  59	  return (before, after) => {
  60	    const beforeProps = getNormalizedProps(before);
  61	    const afterProps = getNormalizedProps(after);
  62	    const beforeResult = schema.safeParse(beforeProps);
  63	    const afterResult = schema.safeParse(afterProps);
  64	
  65	    if (!afterResult.success) return;
  66	
  67	    const oldSettings = beforeResult.success
  68	      ? (beforeResult.data ?? null)
  69	      : null;
  70	    const newSettings = afterResult.data as T;
  71	
  72	    onSettingsChange({ newSettings, oldSettings, before, after });
  73	  };
