 11	import getPageUidByPageTitle from "roamjs-components/queries/getPageUidByPageTitle";
 12	import {
 13	  getSuggestiveModeConfigAndUids,
 14	  SuggestiveModeConfigWithUids,
 15	} from "./getSuggestiveModeConfigSettings";
 16	import {
 17	  getLeftSidebarSettings,
 18	  LeftSidebarConfig,
 19	} from "./getLeftSidebarSettings";
 20	
 21	const configTreeRef: {
 22	  tree: RoamBasicNode[];
 23	  nodes: { [uid: string]: { text: string; children: RoamBasicNode[] } };
 24	} = { tree: [], nodes: {} };
 25	
 26	const listeners = new Set<() => void>();
 27	
 28	export const subscribe = (listener: () => void) => {
 29	  listeners.add(listener);
 30	  return () => listeners.delete(listener);
 31	};
 32	
 33	export const notify = () => {
 34	  listeners.forEach((listener) => listener());
 35	};
 36	
 37	type FormattedConfigTree = {
 38	  settingsUid: string;
 39	  grammarUid: string;
 40	  relationsUid: string;
 41	  nodesUid: string;
 42	  trigger: StringSetting;
 43	  export: ExportConfigWithUids;
 44	  canvasPageFormat: StringSetting;
 45	  suggestiveMode: SuggestiveModeConfigWithUids;
 46	  leftSidebar: LeftSidebarConfig;
 47	  leftSidebarEnabled: BooleanSetting;
 48	};
 49	
 50	export const getFormattedConfigTree = (): FormattedConfigTree => {
 51	  const settingsUid = getPageUidByPageTitle(DISCOURSE_CONFIG_PAGE_TITLE);
 52	  const grammarNode = configTreeRef.tree.find(
 53	    (node) => node.text === "grammar",
 54	  );
 55	  const relationsNode = grammarNode?.children.find(
 56	    (node) => node.text === "relations",
 57	  );
 58	  const nodesNode = grammarNode?.children.find((node) => node.text === "nodes");
 59	
 60	  return {
 61	    settingsUid,
 62	    grammarUid: grammarNode?.uid || "",
 63	    relationsUid: relationsNode?.uid || "",
 64	    nodesUid: nodesNode?.uid || "",
 65	    trigger: getUidAndStringSetting({
 66	      tree: configTreeRef.tree,
 67	      text: "trigger",
 68	    }),
 69	    export: getExportSettingsAndUids(),
 70	    canvasPageFormat: getUidAndStringSetting({
 71	      tree: configTreeRef.tree,
 72	      text: "Canvas Page Format",
 73	    }),
 74	    suggestiveMode: getSuggestiveModeConfigAndUids(configTreeRef.tree),
 75	    leftSidebar: getLeftSidebarSettings(configTreeRef.tree),
