   391	  const { blockUids, propsInitialized } = await initSettingsPageBlocks();
   392	
   393	  // Retrying on the next load is safer than migrating over unfinished defaults.
   394	  if (!propsInitialized) return { blockUids, nodePageUids: {} };
   395	
   396	  if (!discourseConfigRef.tree.some((n) => n.text === "grammar")) {
   397	    refreshConfigTree();
   398	  }
   399	
