   401	  const personalSettingsMigrated = await migratePersonalSettings(blockUids);
   402	  if (graphSettingsMigrated && personalSettingsMigrated) {
   403	    await migratePropsStoreDefault(blockUids);
   404	  }
   405	  (window as unknown as Record<string, unknown>).dgDualReadLog =
