   182	
   183	export const migrateGraphLevel = async (
   184	  blockUids: Record<string, string>,
   185	): Promise<boolean> => {
   186	  const pageUid = getPageUidByPageTitle(DG_BLOCK_PROP_SETTINGS_PAGE_TITLE);
   187	  if (!pageUid) {
   188	    internalError({
   189	      error: `Settings page not found: ${DG_BLOCK_PROP_SETTINGS_PAGE_TITLE}`,
   190	      type: "DG Block Props Migration",
   191	      context: { scope: "graph" },
   192	      sendEmail: false,
   193	    });
   194	    return false;
   195	  }
   196	
   197	  if (hasGraphMigrationMarker(blockUids)) {
   198	    console.log(`${LOG_PREFIX} graph-level: skipped (already migrated)`);
   199	    return true;
   200	  }
   201	
   202	  let failures = 0;
   203	
   204	  const featureFlagUid = blockUids[STATIC_TOP_LEVEL_ENTRIES.featureFlags.key];
   205	  if (!featureFlagUid) {
   266	    failures++;
   267	  }
