import { readFileSync, existsSync } from "node:fs";
import { join, dirname, basename } from "node:path";
import process from "node:process";
import console from "node:console";
import { fileURLToPath } from "node:url";
import dotenv from "dotenv";

// Note: This file is written as mjs so it can be used before typescript compilation.
// This means the corresponding .d.ts file is currently maintained by hand.
// Remember to update it as needed.

const findRoot = () => {
  let dir = fileURLToPath(import.meta.url);
  while (basename(dir) !== "database") {
    dir = dirname(dir);
  }
  return dir;
};
export const getVariant = () => {
  const useDbArgPos = (process.argv || []).indexOf("--use-db");
  let variant =
    useDbArgPos > 0
      ? process.argv[useDbArgPos + 1]
      : process.env["SUPABASE_USE_DB"];
  if (variant === undefined) {
    dotenv.config();
    const dbGlobalEnv = join(findRoot(), ".env");
    if (existsSync(dbGlobalEnv)) dotenv.config({ path: dbGlobalEnv });
    variant = process.env["SUPABASE_USE_DB"];
  }
  const processHasVars =
    !!process.env["SUPABASE_URL"] && !!process.env["SUPABASE_PUBLISHABLE_KEY"];

  if (
    ["local", "branch", "production", "none", "implicit", undefined].indexOf(
      variant,
    ) === -1
  ) {
    throw new Error("Invalid variant: " + variant);
  }

  if (
    process.env.HOME === "/vercel" ||
    (process.env.GITHUB_ACTIONS === "true" &&
      process.env.GITHUB_TEST !== "test")
  ) {
    // deployment should have variables
    if (!processHasVars) {
      console.error("Missing SUPABASE variables in deployment");
      variant = "none";
    } else {
      variant = "implicit";
    }
  }
  if (variant === undefined) {
    if (processHasVars) {
      console.warn(
        "please define explicitly which database to use (set SUPABASE_USE_DB)",
      );
      variant = "implicit";
    } else {
      console.warn("Not using the database");
      variant = "none";
    }
  }
  // avoid repeating warnings
  process.env["SUPABASE_USE_DB"] = variant;
  return variant;
};

export const envFilePath = () => {
  const variant = getVariant();
  if (variant === "implicit" || variant === "none") return null;
  const name = join(findRoot(), `.env.${variant}`);
  return existsSync(name) ? name : null;
};

export const envContents = () => {
  const path = envFilePath();
  if (!path) {
    // Fallback to process.env when running in production environments
    const raw = {
      SUPABASE_URL: process.env.SUPABASE_URL,
      SUPABASE_PUBLISHABLE_KEY: process.env.SUPABASE_PUBLISHABLE_KEY,
      NEXT_API_ROOT: process.env.NEXT_API_ROOT,
    };
    return Object.fromEntries(Object.entries(raw).filter(([, v]) => !!v));
  }
  const data = readFileSync(path, "utf8");
  return dotenv.parse(data);
};

let configDone = false;

export const config = () => {
  if (configDone) return;
  const path = envFilePath();
  if (path) dotenv.config({ path });
  configDone = true;
};
import { execSync } from "node:child_process";
import { appendFileSync, writeFileSync, readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import dotenv from "dotenv";
import { Vercel } from "@vercel/sdk";

const __dirname = dirname(fileURLToPath(import.meta.url));
const projectRoot = join(__dirname, "..");
const baseParams: Record<string, string> = {};

enum Variant {
  local = "local",
  branch = "branch",
  production = "production",
  all = "all",
  none = "none",
}

// option to override in .env, but otherwise use our values
const projectIdOrName: string =
  process.env["VERCEL_PROJECT_ID"] ||
  process.env["VERCEL_PROJECT_NAME"] ||
  "discourse-graph";

const getVercelToken = () => {
  return process.env["VERCEL_TOKEN"];
};

const makeFnEnv = (envTxt: string): string => {
  return envTxt
    .split("\n")
    .filter((l) => l.match(/^SUPABASE_\w+_KEY/))
    .join("\n");
};

const makeLocalEnv = () => {
  execSync("supabase start", {
    cwd: projectRoot,
    stdio: "inherit",
  });
  const stdout = execSync("supabase status -o env", {
    encoding: "utf8",
  });
  const prefixed = stdout
    .split("\n")
    .filter((line) => line.length > 0)
    .map((line) =>
      /^API_URL=/.test(line)
        ? `SUPABASE_URL=${line.substring(8)}`
        : `SUPABASE_${line}`,
    )
    .join("\n");
  writeFileSync(
    join(projectRoot, ".env.local"),
    prefixed + '\nNEXT_API_ROOT="http://localhost:3000/api"\n',
  );
  writeFileSync(
    join(projectRoot, "supabase/functions/.env"),
    makeFnEnv(prefixed),
  );
};

const makeBranchEnv = async (vercel: Vercel, vercelToken: string) => {
  let branch: string;
  if (process.env.SUPABASE_GIT_BRANCH) {
    // allow to override current branch
    // currently test with ENG-589-create-space-fn
    branch = process.env.SUPABASE_GIT_BRANCH;
  } else {
    const stdout = execSync("git status -b -uno", { encoding: "utf8" });
    const branchM = stdout.match(/On branch (.*)/)?.[1];
    if (branchM) branch = branchM;
    else throw new Error("Could not find the git branch");
  }
  if (!/^[-\w]+$/.test(branch))
    throw new Error("Invalid branch name: " + branch);
  const result = await vercel.deployments.getDeployments({
    ...baseParams,
    projectId: projectIdOrName,
    limit: 1,
    branch,
    state: "READY",
  });
  if (result.deployments.length === 0) {
    console.warn("No deployment for branch " + branch);
    return;
  }
  const deployment = result.deployments[0];
  if (!deployment) throw new Error("Could not get deployment");
  const url = deployment.meta?.branchAlias ?? deployment.url;
  try {
    execSync(
      `vercel -t ${vercelToken} env pull --environment preview --git-branch ${branch} .env.branch`,
      { encoding: "utf8" },
    );
  } catch (err) {
    console.error(err);
    throw err;
  }
  appendFileSync(".env.branch", `NEXT_API_ROOT="https://${url}/api"\n`);
  const fromVercel = readFileSync(".env.branch").toString();
  writeFileSync(
    join(projectRoot, "supabase/functions/.env"),
    makeFnEnv(fromVercel),
  );
};

const makeProductionEnv = async (vercel: Vercel, vercelToken: string) => {
  const result = await vercel.projects.getProjectDomains({
    ...baseParams,
    idOrName: projectIdOrName,
    production: "true",
  });
  const domains = result.domains.filter(
    (d) => !d.redirect && d.apexName.indexOf("vercel") < 0,
  );
  if (domains.length === 0) {
    throw new Error("No production domains found");
  }
  if (domains.length > 1) {
    console.log(domains);
    throw new Error("Too many production domains found");
  }
  const url = domains[0]!.name;
  execSync(
    `vercel -t ${vercelToken} env pull --environment production .env.production`,
  );
  appendFileSync(".env.production", `NEXT_API_ROOT="https://${url}/api"\n`);
  const fromVercel = readFileSync(".env.production").toString();
  writeFileSync(
    join(projectRoot, "supabase/functions/.env"),
    makeFnEnv(fromVercel),
  );
};

const main = async (variant: Variant) => {
  if (process.env.ROAM_BUILD_SCRIPT) {
    // special case: production build
    try {
      const response = execSync(
        "curl https://discoursegraphs.com/api/supabase/env",
      );
      const asJson = JSON.parse(response.toString()) as Record<string, string>;
      writeFileSync(
        join(projectRoot, ".env"),
        Object.entries(asJson)
          .map(([k, v]) => `${k}=${v}`)
          .join("\n"),
      );
      return;
    } catch (e) {
      if (process.env.SUPABASE_URL && process.env.SUPABASE_PUBLISHABLE_KEY)
        return;
      throw new Error("Could not get environment from site");
      entryPoints: [path.join(srcRoot, entryTs)],
      outdir,
      bundle: true,
      format,
      define: {
        "process.env.SUPABASE_URL": dbEnv.SUPABASE_URL
          ? `"${dbEnv.SUPABASE_URL}"`
          : "null",
        "process.env.SUPABASE_PUBLISHABLE_KEY": dbEnv.SUPABASE_PUBLISHABLE_KEY
          ? `"${dbEnv.SUPABASE_PUBLISHABLE_KEY}"`
          : "null",
        "process.env.NEXT_API_ROOT": `"${dbEnv.NEXT_API_ROOT || ""}"`,
        "window.__DISCOURSE_GRAPH_VERSION__": `"${getVersion()}"`,
        "window.__DISCOURSE_GRAPH_BUILD_DATE__": `"${getBuildDate()}"`,
        "window.__DISCOURSE_GRAPH_BUILD_COMMIT__": `"${getBuildCommit()}"`,
        "window.__DISCOURSE_GRAPH_BUILD_BRANCH__": `"${getBuildBranch()}"`,
      },
      sourcemap: process.env.NODE_ENV === "production" ? "external" : "inline",
      minify: process.env.NODE_ENV === "production",
      entryNames: out,
      external: externalModules.map(([e]) => e).concat(["crypto"]),
      plugins: [
        importAsGlobals(
          Object.fromEntries(
            externalModules
              .filter((e) => e.length > 1)
              .map(([e, ...g]) => [e, g.join("=")]),
          ),
        ),
        {
          name: "log",
          setup: (build) => {
            build.onEnd((result) => {
              console.log(`built with ${result.errors.length} errors`);
            });
          },
        },
        addPlaceholderChangelogPlugin(outdir),
        {
          name: "onFinish",
          setup(build) {
            build.onEnd(async () => {
              DEFAULT_FILES_INCLUDED.map((f) => path.join(root, f))
                .filter((f) => fs.existsSync(f))
                .forEach((f) => {
                  fs.cpSync(f, path.join(outdir, path.basename(f)));
                });
            });
          },
        },
      ],
      loader: {
        ".woff": "file",
        ".woff2": "file",
        ".yaml": "text",
      },
    }),
  );

  return Promise.all(buildPromises);
};

const main = async () => {
  try {
    await compile({});
  } catch (error) {
    console.error(error);
    process.exit(1);
  }
};
if (require.main === module) main();

