const __dirname = dirname(fileURLToPath(import.meta.url));
const projectRoot = join(__dirname, "..");
const baseParams: Record<string, string> = {};

enum Variant {
  local = "local",
  branch = "branch",
  production = "production",
  all = "all",
  none = "none",
}

