import esbuild from "esbuild";
import { execSync } from "child_process";
import fs from "fs";
import path from "path";
import { z } from "zod";
import { importAsGlobals } from "./importAsGlobals";

const getVersion = (): string => {
  try {
    const packageJson = JSON.parse(
      fs.readFileSync(path.join(process.cwd(), "package.json"), "utf8"),
    ) as { version?: string };
    return packageJson.version || "-";
  } catch (error) {
    console.warn("Failed to read version from package.json:", error);
    return "-";
  }
};

const getBuildDate = (): string => {
  return new Date().toISOString().split("T")[0]; // YYYY-MM-DD format
};

const runGitCommand = (command: string): string | undefined => {
  try {
    return execSync(command, {
      cwd: process.cwd(),
      stdio: ["ignore", "pipe", "ignore"],
    })
      .toString()
      .trim();
  } catch {
    return undefined;
  }
};

const getBuildCommit = (): string => {
  return (
    process.env.DISCOURSE_GRAPH_BUILD_COMMIT ||
    process.env.GITHUB_SHA ||
    runGitCommand("git rev-parse HEAD") ||
    "-"
  );
};

const getBuildBranch = (): string => {
  return (
    process.env.DISCOURSE_GRAPH_BUILD_BRANCH ||
    process.env.GITHUB_HEAD_REF ||
    process.env.GITHUB_REF_NAME ||
    runGitCommand("git rev-parse --abbrev-ref HEAD") ||
    "-"
  );
};
let envContents = null;

try {
  const dbDotEnv = require("@repo/database/dbDotEnv");
  envContents = dbDotEnv.envContents;
} catch (error) {
  if ((error as Error).message.includes("Cannot find module")) {
    console.error("Build the database module before compiling roam");
    process.exit(1);
  }
  throw error;
}

const DEFAULT_FILES_INCLUDED = ["package.json", "README.md"];

const addPlaceholderChangelogPlugin = (outdir: string): esbuild.Plugin => ({
  name: "add-changelog",
  setup(build) {
    build.onEnd(async () => {
      fs.writeFileSync(path.join(outdir, "CHANGELOG.md"), "placeholder");
    });
  },
});

const cliArgs = z.object({
  out: z.string().optional(),
  root: z.string().optional(),
  format: z.enum(["esm"]).optional(),
  external: z.array(z.string()),
});

type Builder = (opts: esbuild.BuildOptions) => Promise<void>;
export type CliOpts = Record<string, string | string[] | boolean>;

export const args = {
  out: "extension",
  format: "esm",
  root: ".",
  mirror: ".",
  external: [
    "react-dom/client=window.ReactDOM",
    "@blueprintjs/core=window.Blueprint.Core",
    "@blueprintjs/datetime=window.Blueprint.DateTime",
    "@blueprintjs/select=window.Blueprint.Select",
    "chrono-node=window.ChronoNode",
    "crypto-js=window.CryptoJS",
    "cytoscape=window.RoamLazy.Cytoscape",
    "file-saver=window.FileSaver",
    "jszip=window.RoamLazy.JSZip",
    "idb=window.idb",
    "insect=window.RoamLazy.Insect",
    "marked=window.RoamLazy.Marked",
    "marked-react=window.RoamLazy.MarkedReact",
    "nanoid=window.Nanoid;module.exports.nanoid=window.Nanoid",
    "react=./scripts/react.cjs",
    "react/jsx-runtime=./node_modules/react/jsx-runtime.js",
    "react-dom=window.ReactDOM",
    "react-youtube=window.ReactYoutube",
    "tslib=window.TSLib",
  ],
} as CliOpts;

export const compile = ({
  opts = args,
  builder = async (opts) => {
    await esbuild.build(opts);
  },
}: {
  opts?: CliOpts;
  builder?: Builder;
}) => {
  const { root = ".", out, format, external } = cliArgs.parse(opts);

  const externalModules = external.map((e) => e.split("="));
  const srcRoot = path.join(root, "src");
  const entryTs = "index.ts";
  const outdir = path.resolve(process.cwd(), root, "dist");

  fs.mkdirSync(outdir, { recursive: true });

  const buildPromises = [] as Promise<void>[];
  const dbEnv = envContents();
  buildPromises.push(
    builder({
      absWorkingDir: process.cwd(),
      entryPoints: [path.join(srcRoot, entryTs)],
      throw new Error("Could not get environment from site");
    }
  } else if (
    process.env.HOME === "/vercel" ||
    (process.env.GITHUB_ACTIONS === "true" &&
      process.env.GITHUB_TEST !== "test")
  )
    // Do not execute in deployment or github action.
    return;

  if (variant === Variant.none) return;

  try {
    if (variant === Variant.local || variant === Variant.all) {
      makeLocalEnv();
      if (variant === Variant.local) return;
    }
    const vercelToken = getVercelToken();
    if (!vercelToken) {
      throw Error("Missing VERCEL_TOKEN in .env");
    }
    // option to override in .env, but otherwise use our values
    const teamId = process.env["VERCEL_TEAM_ID"];
    const teamSlug = process.env["VERCEL_TEAM_SLUG"] || "discourse-graphs";
    if (teamId) {
      baseParams.teamId = teamId;
    } else {
      baseParams.slug = teamSlug;
    }
    const vercel = new Vercel({ bearerToken: vercelToken });
    if (variant === Variant.branch || variant === Variant.all) {
      await makeBranchEnv(vercel, vercelToken);
    }
    if (variant === Variant.production || variant === Variant.all) {
      await makeProductionEnv(vercel, vercelToken);
    }
  } catch (err) {
    console.error("variant ", variant, " error ", err);
    throw err;
  }
};

if (fileURLToPath(import.meta.url) === process.argv[1]) {
  dotenv.config();
  const variantS: string =
    (process.argv.length === 3
      ? process.argv[2]
      : process.env["SUPABASE_USE_DB"]) || "none";

  const variant = (Variant as Record<string, Variant>)[variantS];
  if (variant === undefined) {
    throw Error("Invalid variant: " + variant);
  }
  console.log(variant);
  await main(variant);
}
