tools.exec_command({cmd:"git status --short --branch\ngit log -2 --format=full\ncommand -v entire\nrg --files --hidden .entire .husky .codex .claude 2>/dev/null\nrg -n -i 'entire' .git/config .git/hooks .husky .entire .codex .claude .gitignore AGENTS.md 2>/dev/null","max_output_tokens":3800}),
tools.exec_command({cmd:"rg -n -i -m 12 '\\bentire\\b' /home/sid/.codex/memories/MEMORY.md","max_output_tokens":1600}),
tools.exec_command({cmd:"gh pr view 1468 --json url,isDraft,headRefOid,statusCheckRollup\ngit show --stat 94760b50","max_output_tokens":3000})
]);results.forEach((r,i)=>text({i,...r}));

